`default_nettype none

module tt_um_vga_example (
    input  wire [7:0] ui_in,    
    output wire [7:0] uo_out,   
    input  wire [7:0] uio_in,   
    output wire [7:0] uio_out,  
    output wire [7:0] uio_oe,   
    input  wire       ena,      
    input  wire       clk,      
    input  wire       rst_n     
);
    wire _unused_ok = &{ena, ui_in, uio_in, 1'b0, rst_n};
    assign uio_out = 0;
    assign uio_oe  = 0;

    wire hsync;
    wire vsync;
    reg [1:0] R;
    reg [1:0] G;
    reg [1:0] B;
    wire video_active;
    wire [9:0] pix_x;
    wire [9:0] pix_y;

    assign uo_out = {hsync, B[0], G[0], R[0], vsync, B[1], G[1], R[1]};

    hvsync_generator vga_sync_gen (
        .clk(clk),
        .reset(1'b0), 
        .hsync(hsync),
        .vsync(vsync),
        .display_on(video_active),
        .hpos(pix_x),
        .vpos(pix_y)
    );

    wire [9:0] start_x = 64; 
    wire [9:0] start_y = 48; 
    wire in_window = (pix_x >= start_x && pix_x < start_x + 512) &&
                     (pix_y >= start_y && pix_y < start_y + 384);

    wire [4:0] vid_x = (pix_x >= start_x) ? 5'((pix_x - start_x) >> 4) : 5'd0;
    wire [4:0] vid_y = (pix_y >= start_y) ? 5'((pix_y - start_y) >> 4) : 5'd0;

    reg [3:0] refresh_divider; 
    reg [10:0] frame_counter;
    reg last_vsync;
    
   parameter TOTAL_FRAMES = 1096; 

    initial begin
        frame_counter = 0; 
        refresh_divider = 0;
        last_vsync = 0;
    end

    always @(posedge clk) begin
        last_vsync <= vsync;
        if (last_vsync && !vsync) begin
            if (refresh_divider == 11) begin // 60Hz / 12 = 5 FPS
                refresh_divider <= 0;
                frame_counter <= (frame_counter >= TOTAL_FRAMES - 1) ? 11'd0 : frame_counter + 11'd1;
            end else begin
                refresh_divider <= refresh_divider + 4'd1;
            end
        end
    end

    wire pixel_value;
    
    video_rom my_rom (
        .frame(frame_counter),
        .x(vid_x),
        .y(vid_y),
        .pixel(pixel_value)
    );

    always @(*) begin
        if (video_active && in_window && pixel_value) begin
            R = 2'b11;
            G = 2'b11;
            B = 2'b11;
        end else begin
            R = 2'b00;
            G = 2'b00;
            B = 2'b00;
        end
    end

endmodule

module hvsync_generator (
    input  wire       clk,
    input  wire       reset,
    output reg        hsync,
    output reg        vsync,
    output wire       display_on,
    output reg  [9:0] hpos,
    output reg  [9:0] vpos
);
    parameter H_DISPLAY    = 640;
    parameter H_FRONT      = 16;
    parameter H_SYNC       = 96;
    parameter H_BACK       = 48;
    parameter V_DISPLAY    = 480;
    parameter V_BOTTOM     = 10;
    parameter V_SYNC       = 2;
    parameter V_TOP        = 33;
    parameter H_SYNC_START = H_DISPLAY + H_FRONT;
    parameter H_SYNC_END   = H_DISPLAY + H_FRONT + H_SYNC - 1;
    parameter H_MAX        = H_DISPLAY + H_FRONT + H_SYNC + H_BACK - 1;
    parameter V_SYNC_START = V_DISPLAY + V_BOTTOM;
    parameter V_SYNC_END   = V_DISPLAY + V_BOTTOM + V_SYNC - 1;
    parameter V_MAX        = V_DISPLAY + V_BOTTOM + V_SYNC + V_TOP - 1;

    wire hmaxxed = (hpos == H_MAX) || reset;
    wire vmaxxed = (vpos == V_MAX) || reset;

    always @(posedge clk) begin
        hsync <= ~(hpos >= H_SYNC_START && hpos <= H_SYNC_END);
        if (hmaxxed) hpos <= 0;
        else hpos <= hpos + 10'd1;
    end

    always @(posedge clk) begin
        vsync <= ~(vpos >= V_SYNC_START && vpos <= V_SYNC_END);
        if (hmaxxed) begin
            if (vmaxxed) vpos <= 0;
            else vpos <= vpos + 10'd1;
        end
    end

    assign display_on = (hpos < H_DISPLAY) && (vpos < V_DISPLAY);
endmodule


